item.content:encoded:
.floating-banner {
  display: block;
  position: fixed;
  z-index: 9999;
  bottom: 0;
  width: 100%;
  right: 0;
  background-color: #06C755;
}
.floating-banner a.banner {
  text-decoration: none;
  height: 3em;
  color: #fff;
  text-align: center;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 1.25em;
}
.floating-banner a.banner i {
  margin-right: 0.2em;
}
